using CustomerService.Application.Terms;using CustomerService.Domain.Dtos;using MediatR;using Microsoft.AspNetCore.Mvc;namespace CustomerService.Api.Controllers;[ApiController][Route("api/v1/terms")][Produces("application/json")]public sealed class TermsController(ISender sender):ControllerBase{[HttpGet]public async Task<ActionResult<ApiResponse<IReadOnlyList<TermDocumentDto>>>> GetAll(CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<TermDocumentDto>>.Ok(await sender.Send(new GetActiveTermsQuery(),ct),"Active terms retrieved.",HttpContext.TraceIdentifier));[HttpGet("{id:guid}")]public async Task<ActionResult<ApiResponse<TermDocumentDto>>> Get(Guid id,CancellationToken ct)=>Ok(ApiResponse<TermDocumentDto>.Ok(await sender.Send(new GetTermQuery(id),ct),"Term retrieved.",HttpContext.TraceIdentifier));}
